// Rebuilds the card browser and the shuffle table on public/index.html from the card list inside it.
// The list is the JSON in <script id="deck-data">. To add, remove or reword a card: edit that JSON, put the card face in
// public/cards/<slug>.webp, run `node tools/make-thumbs.cjs`, then run `node tools/build-index.cjs` (and `py tools/printables/build_sw.py`).
// Everything between <!-- deck:start --> and <!-- deck:end --> is generated; do not edit it by hand.
const fs = require("fs"), path = require("path");
const ROOT = path.join(__dirname, "..", "public");
const FILE = path.join(ROOT, "index.html");

const SUITS = [
  { k: "B", title: "#305f82" },
  { k: "G", title: "#066633" },
  { k: "Y", title: "#7a5a00" },
  { k: "R", title: "#b13b55" },
];
const esc = (s) => String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
const CHEV = (d) => `<svg viewBox="0 0 24 24" width="20" height="20" aria-hidden="true" focusable="false"><path d="${d}" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"/></svg>`;

let html = fs.readFileSync(FILE, "utf8");
const crlf = html.includes("\r\n");
html = html.replace(/\r\n/g, "\n");

const m = html.match(/(<script type="application\/json" id="deck-data">)([\s\S]*?)(<\/script>)/);
if (!m) throw new Error("deck-data not found");
const deck = JSON.parse(m[2]);

/* The time label printed on each card page (for example "3–5 min" or "Whole lesson"), so the home page says the same thing. */
function timeLabel(c) {
  try {
    const page = fs.readFileSync(path.join(ROOT, c.slug + ".html"), "utf8");
    const b = page.match(/<span class="badge">([^<]*)<\/span>/);
    if (b && b[1].trim()) return b[1].trim();
  } catch (e) {}
  return c.mins > 0 ? `~${c.mins} min` : "Whole lesson";
}
deck.forEach((c) => { c.time = timeLabel(c); });

const search = (c) => `${c.card} ${c.tagline} ${c.move} ${c.suitName}`.toLowerCase();

function suitStyle(k) {
  const s = SUITS.find((x) => x.k === k);
  const c = deck.find((x) => x.suit === k);
  return `--suit:${c.color};--title:${s.title}`;
}

function li(c) {
  const meta = c.time + (c.noprep ? " · No prep" : "");
  return `<li class="s${c.suit}" style="${suitStyle(c.suit)}" data-slug="${c.slug}" data-suit="${c.suit}" data-mins="${c.mins}" data-noprep="${c.noprep ? 1 : 0}" data-ev="${esc(c.ev)}" data-time="${esc(c.time)}" data-search="${esc(search(c))}">` +
    `<a href="/${c.slug}" draggable="false"><img class="face" src="/cards/t/${c.slug}.webp" alt="" width="440" height="755" loading="lazy" decoding="async" draggable="false">` +
    `<span class="cap"><span class="nm">${esc(c.card)}</span><span class="tg">${esc(c.tagline)}</span><span class="idx">${esc(meta)}<i class="tick" aria-label="tried"></i></span></span></a></li>`;
}

const groups = SUITS.map((s) => ({ s, cards: deck.filter((c) => c.suit === s.k) }));
const list = groups.map(({ s, cards }) => {
  const first = cards[0];
  return `<li class="divider s${s.k}" style="${suitStyle(s.k)}" data-suit="${s.k}"><div class="dv"><h2>${esc(first.suitName)}</h2><p class="dv-n">${cards.length} cards</p></div></li>` + cards.map(li).join("");
}).join("\n");

const chips = groups.map(({ s, cards }) => `<button type="button" class="chip" data-suit="${s.k}" aria-pressed="false" style="--suit:${cards[0].color}"><i></i>${esc(cards[0].suitName)}</button>`).join("");

const block = `<!-- deck:start (generated by tools/build-index.cjs; edit the deck-data list, not this block) -->
<section class="table" id="table" aria-label="Your dealt card" hidden>
  <div class="wrap table-in">
    <div class="stage" id="stage" aria-hidden="true"></div>
    <div class="dealt" id="dealt" role="status">
      <p class="d-wait">Shuffling the deck…</p>
      <div class="d-info">
        <p class="d-idx"></p>
        <p class="d-name"></p>
        <p class="d-tag"></p>
        <p class="d-move"></p>
        <p class="d-meta"></p>
        <div class="d-actions"><a class="d-go btn-main" href="#">Open this card</a><button type="button" class="btn-ghost" id="again">Shuffle again</button></div>
      </div>
      <button type="button" class="d-away" id="put-away">Put the deck away</button>
    </div>
  </div>
</section>
<main class="wrap" id="main">
<section class="browse" aria-labelledby="browse-h">
<h2 class="sr" id="browse-h">All ${deck.length} cards</h2>
<div class="filters" role="search">
<div class="filters-top"><label class="sr" for="q">Search cards</label><input id="q" type="search" placeholder="Search the deck…" autocomplete="off">
<p class="count muted" id="count" aria-live="polite"></p>
<div class="viewsw" role="group" aria-label="How to show the cards"><button type="button" data-view="fan" aria-pressed="true">Fan</button><button type="button" data-view="grid" aria-pressed="false">Grid</button></div></div>
<div class="chips">${chips}<button type="button" class="chip" data-toggle="quick" aria-pressed="false">5 min or less</button><button type="button" class="chip" data-toggle="noprep" aria-pressed="false">No prep</button><button type="button" class="chip" data-toggle="strong" aria-pressed="false">Strong evidence</button><button type="button" class="chip" data-toggle="tried" aria-pressed="false">Tried</button></div>
</div>
<div class="deckbar" id="deckbar">
<button type="button" class="nav-btn" id="prev" aria-label="Previous card">${CHEV("M15 5l-7 7 7 7")}</button>
<div class="rail" id="rail" aria-hidden="true">${groups.map(({ s, cards }) => `<span class="rail-seg s${s.k}" data-suit="${s.k}" style="--suit:${cards[0].color};flex-grow:${cards.length}"></span>`).join("")}<span class="rail-knob"></span></div>
<button type="button" class="nav-btn" id="next" aria-label="Next card">${CHEV("M9 5l7 7-7 7")}</button>
<p class="pos" id="pos" aria-hidden="true"></p>
</div>
<ul class="cards" id="cards">
${list}
</ul>
<div class="hand-cap" id="hand-cap" aria-hidden="true"><p class="hc-suit"></p><p class="hc-nm"></p><p class="hc-tg"></p><p class="hc-meta"></p></div>
<p class="none" id="none" hidden>No cards match. Clear the search or switch a filter off.</p>
</section>
</main>
<!-- deck:end -->`;

/* swap in the new block */
const start = html.indexOf("<!-- deck:start");
const end = html.indexOf("<!-- deck:end -->");
if (start >= 0 && end > start) {
  html = html.slice(0, start) + block + html.slice(end + "<!-- deck:end -->".length);
} else {
  const a = html.indexOf('<main class="wrap" id="main">'), b = html.indexOf("</main>");
  if (a < 0 || b < a) throw new Error("main block not found");
  html = html.slice(0, a) + block + html.slice(b + "</main>".length);
}
/* the card list, with the time label added, for the shuffle */
html = html.replace(/(<script type="application\/json" id="deck-data">)([\s\S]*?)(<\/script>)/, (_, a, __, c) => a + JSON.stringify(deck) + c);

if (crlf) html = html.replace(/\n/g, "\r\n");
fs.writeFileSync(FILE, html);
console.log("index rebuilt:", deck.length, "cards,", new Set(deck.map((c) => c.time)).size, "time labels:", [...new Set(deck.map((c) => c.time))].join(" | "));
